import { CHARSET_REV, GENERATORS } from "./constants.mjs";

export function bech32Polymod(values) {
  let checksum = 1;

  for (const value of values) {
    const top = checksum >>> 25;
    checksum = ((checksum & 0x1ffffff) << 5) ^ value;

    for (let index = 0; index < GENERATORS.length; index += 1) {
      if (((top >>> index) & 1) !== 0) {
        checksum ^= GENERATORS[index];
      }
    }
  }

  return checksum;
}

export function expandHrp(hrp) {
  const result = [];

  for (const character of hrp) {
    const codePoint = character.codePointAt(0);
    result.push(codePoint >>> 5);
  }

  result.push(0);

  for (const character of hrp) {
    const codePoint = character.codePointAt(0);
    result.push(codePoint & 31);
  }

  return result;
}

export function verifyChecksum(hrp, data) {
  return bech32Polymod([...expandHrp(hrp), ...data]) === 1;
}

export function decodeBech32(address) {
  for (const character of address) {
    const codePoint = character.codePointAt(0);

    if (codePoint < 33 || codePoint > 126) {
      return [null, null];
    }
  }

  if (address !== address.toLowerCase() && address !== address.toUpperCase()) {
    return [null, null];
  }

  const normalized = address.toLowerCase();
  const separatorIndex = normalized.lastIndexOf("1");

  if (separatorIndex < 1 || separatorIndex + 7 > normalized.length || normalized.length > 90) {
    return [null, null];
  }

  const hrp = normalized.slice(0, separatorIndex);
  const data = [];

  for (const character of normalized.slice(separatorIndex + 1)) {
    const value = CHARSET_REV[character];

    if (value === undefined) {
      return [null, null];
    }

    data.push(value);
  }

  if (!verifyChecksum(hrp, data)) {
    return [null, null];
  }

  return [hrp, data.slice(0, -6)];
}

export function convertBits(data, fromBits, toBits, pad = true) {
  let accumulator = 0;
  let bits = 0;
  const result = [];
  const maxValue = (1 << toBits) - 1;
  const maxAccumulator = (1 << (fromBits + toBits - 1)) - 1;

  for (const value of data) {
    if (value < 0 || (value >> fromBits) !== 0) {
      return null;
    }

    accumulator = ((accumulator << fromBits) | value) & maxAccumulator;
    bits += fromBits;

    while (bits >= toBits) {
      bits -= toBits;
      result.push((accumulator >> bits) & maxValue);
    }
  }

  if (pad) {
    if (bits > 0) {
      result.push((accumulator << (toBits - bits)) & maxValue);
    }
  } else if (bits >= fromBits || ((accumulator << (toBits - bits)) & maxValue) !== 0) {
    return null;
  }

  return result;
}

